/// One dense WMMA output element: `kind` 0..4 = fp8_fp8, fp8_bf8, bf8_fp8, bf8_bf8; `a`/`b` the 16 raw codes of the A row /
/// B column in physical K order, `c` the accumulator input, `d` the hardware result word. `tag` names why it was kept.
pub struct WmmaCase {
    pub tag: &'static str,
    pub kind: u8,
    pub a: [u8; 16],
    pub b: [u8; 16],
    pub c: u32,
    pub d: u32,
}

